const LeadsFeature={id:"leads",name:"Leads",icon:"person_add",route:!1,render(){return this.renderScreen()},async renderScreen(){return`<div class="fade-in">\n      ${App.renderTopHeader({title:"Lead inbox",showBack:!0,backHref:"followups",actions:'<button class="btn btn-sm btn-primary" data-action="LeadsFeature.openAddLead">\n          <span class="material-symbols-rounded">add</span> Enquiry\n        </button>'})}\n      <div class="px-md pb-lg">${await this.renderInbox()}</div>\n    </div>`},async renderInbox(){let e=[];try{e=await DB.getLeads()}catch(e){return console.error("Lead inbox failed:",e),'<div class="empty-state"><span class="material-symbols-rounded">error</span><div>Could not load enquiries</div></div>'}const t=e.filter(e=>!["converted","lost"].includes(e.status)),a=e.filter(e=>["converted","lost"].includes(e.status)),s=Date.now(),n=t.filter(e=>!e.nextActionAt||new Date(e.nextActionAt).getTime()<=s),o=t.filter(e=>e.nextActionAt&&new Date(e.nextActionAt).getTime()>s);return e.length?`${this.renderGroup("Needs action",n)}\n      ${this.renderGroup("Upcoming",o)}\n      ${a.length?`<details class="mt-md"><summary class="section-label">Closed (${a.length})</summary>${a.map(e=>this.renderLeadCard(e)).join("")}</details>`:""}`:'<div class="empty-state empty-state-lg">\n      <span class="material-symbols-rounded">person_add</span>\n      <div class="fw-600 mb-xs">No enquiries yet</div>\n      <div class="fs-13">Save a new lead before a visit has been arranged.</div>\n      <button class="btn btn-primary btn-sm mt-md" data-action="LeadsFeature.openAddLead"><span class="material-symbols-rounded">add</span>Add enquiry</button>\n    </div>'},renderGroup(e,t){return t.length?`<div class="section-label">${e} (${t.length})</div>${t.map(e=>this.renderLeadCard(e)).join("")}`:""},renderLeadCard(e){const t=e.name||e.fullName||[e.firstName,e.lastName].filter(Boolean).join(" ")||"Unnamed enquiry",a=e.phone||"",s=e.status||"new",n=e.nextActionAt?Utils.formatDate(e.nextActionAt,"short"):"Action needed",o=!["converted","lost"].includes(s);return`<article class="card mb-sm" data-lead-id="${e.id}">\n      <div class="flex items-start justify-between gap-sm">\n        <div class="min-w-0">\n          <div class="fw-600 ellipsis">${Utils.escapeHtml(t)}</div>\n          <div class="fs-12 text-tertiary">${Utils.escapeHtml(e.source||"Manual")} · ${Utils.escapeHtml(n)}</div>\n        </div>\n        <span class="badge">${Utils.escapeHtml(s.replace(/_/g," "))}</span>\n      </div>\n      ${e.notes?`<div class="fs-13 text-secondary mt-8">${Utils.escapeHtml(e.notes)}</div>`:""}\n      <div class="flex gap-sm mt-10">\n        ${a?`<a class="btn btn-outline btn-sm" href="tel:${Utils.escapeHtml(a)}" aria-label="Call ${Utils.escapeHtml(t)}"><span class="material-symbols-rounded fs-16">call</span>Call</a>`:""}\n        ${o?`<button class="btn btn-primary btn-sm flex-1" data-action="LeadsFeature.bookVisit" data-args='${JSON.stringify([e.id])}'><span class="material-symbols-rounded fs-16">event</span>Book visit</button>`:""}\n        <button class="btn btn-ghost btn-sm" aria-label="Lead actions" data-action="LeadsFeature.openLead" data-args='${JSON.stringify([e.id])}'><span class="material-symbols-rounded">more_horiz</span></button>\n      </div>\n    </article>`},openAddLead(){const e=Utils.formatDate(new Date,"iso");"undefined"!=typeof NoteCapture&&NoteCapture.setRecordings("lead-notes",[]),App.openModal(`<div class="sheet-handle"></div>\n      <div class="sheet-header"><h3>New enquiry</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div>\n      <div class="sheet-body">\n        <div class="form-group"><label for="lead-name">Name</label><input class="input" id="lead-name" autocomplete="name"></div>\n        <div class="form-group"><label for="lead-phone">Phone</label><input class="input" id="lead-phone" type="tel" inputmode="tel" autocomplete="tel"></div>\n        <div class="form-group"><label for="lead-address">Address</label><input class="input" id="lead-address" autocomplete="street-address"></div>\n        <div class="form-group"><label for="lead-source">Source</label><select class="select" id="lead-source">${CONFIG.leadSources.map(e=>`<option value="${e.toLowerCase().replace(/\s+/g,"_")}">${Utils.escapeHtml(e)}</option>`).join("")}</select></div>\n        <div class="form-group"><label for="lead-next-action">Next action</label><input class="input" id="lead-next-action" type="date" value="${e}"></div>\n        <div class="form-group"><label for="lead-notes">Notes</label><textarea class="textarea" id="lead-notes" placeholder="What did they ask about?"></textarea>${"undefined"!=typeof NoteCapture?NoteCapture.render("lead-notes"):""}</div>\n        <div class="hint mb-md">Add a name or phone number. You can book the visit later.</div>\n        <button class="btn btn-primary btn-block" id="lead-save-btn" data-action="LeadsFeature.saveLead">Save enquiry</button>\n      </div>`)},async saveLead(){const e=document.getElementById("lead-name")?.value.trim()||"",t=document.getElementById("lead-phone")?.value.trim()||"";if(!e&&!t)return Toast.show("Add a name or phone number","warning");const a=document.getElementById("lead-save-btn");if(!a?.disabled){a&&(a.disabled=!0);try{const a=document.getElementById("lead-address")?.value.trim()||"",s=document.getElementById("lead-next-action")?.value||"";await DB.addLead({name:e,phone:t,address:a?{line1:a}:null,source:document.getElementById("lead-source")?.value||"manual",status:"new",receivedAt:(new Date).toISOString(),nextActionAt:s?new Date(`${s}T09:00:00`).toISOString():null,notes:document.getElementById("lead-notes")?.value.trim()||"",audioNotes:"undefined"!=typeof NoteCapture?NoteCapture.getRecordings("lead-notes"):[]}),App.closeModal(),Toast.show("Enquiry saved","success"),App.navigate("leads")}catch(e){console.error("Save lead failed:",e),a&&(a.disabled=!1),Toast.show("Could not save enquiry","error")}}},bookVisit(e){App.navigate("appointments",{action:"add",leadId:e})},async openLead(e){const t=await DB.getLead(e);if(!t)return Toast.show("Enquiry not found","error");const a="converted"===t.status;App.openModal(`<div class="sheet-handle"></div>\n      <div class="sheet-header"><h3>${Utils.escapeHtml(t.name||t.fullName||"Enquiry")}</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div>\n      <div class="sheet-body">\n        ${t.phone?`<div class="fs-14 text-secondary mb-sm">${Utils.escapeHtml(t.phone)}</div>`:""}\n        ${t.notes?`<div class="card inset-dark mb-md">${Utils.escapeHtml(t.notes)}</div>`:""}\n        ${a&&t.appointmentId?`<button class="btn btn-primary btn-block" data-close="1" data-action="App.navigate" data-args='${JSON.stringify(["appointments",{id:t.appointmentId}])}'>Open visit</button>`:""}\n        ${a?"":`<button class="btn btn-primary btn-block" data-close="1" data-action="LeadsFeature.bookVisit" data-args='${JSON.stringify([t.id])}'><span class="material-symbols-rounded">event</span>Book visit</button>\n          <button class="btn btn-outline btn-block mt-sm" data-action="LeadsFeature.convertCustomer" data-args='${JSON.stringify([t.id])}'>Create customer only</button>\n          <button class="btn btn-outline btn-block mt-sm" data-action="LeadsFeature.markContacted" data-args='${JSON.stringify([t.id])}'>Mark contacted</button>\n          <button class="btn btn-outline btn-block mt-sm" data-action="LeadsFeature.openSnooze" data-args='${JSON.stringify([t.id])}'>Choose next action</button>\n          <button class="btn btn-ghost btn-block mt-sm text-danger" data-action="LeadsFeature.markLost" data-args='${JSON.stringify([t.id])}'>Mark lost</button>`}\n      </div>`)},async convertCustomer(e){try{const t=await DB.convertLeadToCustomer(e);App.closeModal(),Toast.show("Customer created","success"),App.navigate("customer",{id:t.customer.id})}catch(e){console.error("Lead conversion failed:",e),Toast.show("Could not create customer","error")}},async markContacted(e){await DB.updateLead(e,{status:"contacted",contactedAt:(new Date).toISOString()}),App.closeModal(),Toast.show("Marked contacted","success"),App.navigate("leads")},openSnooze(e){const t=new Date;t.setDate(t.getDate()+1),App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Next action</h3></div><div class="sheet-body">\n      <div class="form-group"><label for="lead-snooze-date">Remind me on</label><input class="input" id="lead-snooze-date" type="date" value="${Utils.formatDate(t,"iso")}"></div>\n      <button class="btn btn-primary btn-block" data-action="LeadsFeature.saveSnooze" data-args='${JSON.stringify([e])}'>Save next action</button>\n      <button class="btn btn-outline btn-block mt-sm" data-action="App.closeModal">Cancel</button>\n    </div>`)},async saveSnooze(e){const t=document.getElementById("lead-snooze-date")?.value||"";if(!t)return Toast.show("Choose a date","warning");await DB.updateLead(e,{nextActionAt:new Date(`${t}T09:00:00`).toISOString()}),App.closeModal(),Toast.show("Next action saved","success"),App.navigate("leads")},markLost(e){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Why was it lost?</h3></div><div class="sheet-body">\n      <div class="form-group"><label for="lead-loss-reason">Reason</label><textarea class="textarea" id="lead-loss-reason"></textarea></div>\n      <button class="btn btn-danger btn-block" data-action="LeadsFeature.saveLost" data-args='${JSON.stringify([e])}'>Mark lost</button>\n      <button class="btn btn-outline btn-block mt-sm" data-action="App.closeModal">Cancel</button>\n    </div>`)},async saveLost(e){const t=document.getElementById("lead-loss-reason")?.value.trim()||"";if(!t)return Toast.show("Add a reason","warning");await DB.updateLead(e,{status:"lost",lossReason:t,lostAt:(new Date).toISOString()}),App.closeModal(),Toast.show("Enquiry closed","success"),App.navigate("leads")}};App.registerFeature(LeadsFeature);
